import { folders, indexLines } from './format.ts';

export function render(dir: string): string {
  let text =
    "# Memory\n\nGenerated by `devkit memory reindex` from each folder's INDEX.md. Do not edit.\n";
  for (const folder of folders(dir)) {
    const lines = indexLines(dir, folder);
    if (lines === null) continue;
    text += `\n## ${folder}\n\n${lines.map((line) => line.replace('](', `](${folder}/`)).join('\n')}\n`;
  }
  return text;
}
